const F=require('./native-fixtures-20261003.cjs'),e=F.environment(),c=e.ctx,x=F.examples(c),N=c.JYNativeAnalysis,plain=v=>JSON.parse(JSON.stringify(v)),results=[],prompts=[],audits=[];
function test(name,fn){try{fn();results.push({name,status:'passed'});console.log('PASS '+name);}catch(e){results.push({name,status:'failed',error:e.stack});process.exitCode=1;console.error('FAIL '+name+' '+e.stack);}}
// Independent inverse of the export notation, including scalar pointers.
function restore(encoded){
 function walk(v,seen=new Set()){
  if(v===null||typeof v!=='object')return v;
  if(Array.isArray(v))return v.map(p=>walk(p,seen));
  if(Object.keys(v).length===1&&typeof v.$ref==='string'){
   assert(v.$ref.startsWith('#/'));assert(!seen.has(v.$ref),'reference cycle');
   let target=encoded;for(const key of v.$ref.slice(2).split('/').map(p=>p.replace(/~1/g,'/').replace(/~0/g,'~'))){assert(Object.hasOwn(target,key));target=target[key];}
   return walk(target,new Set([...seen,v.$ref]));
  }
  return Object.fromEntries(Object.entries(v).map(([k,p])=>[k,walk(p,seen)]));
 }
 function tables(v){
  if(v===null||typeof v!=='object')return v;
  if(Array.isArray(v))return v.map(tables);
  if(Array.isArray(v.$table)&&Array.isArray(v.rows))return v.rows.map(row=>{assert.equal(row.length,v.$table.length);return Object.fromEntries(v.$table.map((k,i)=>[k,tables(row[i])]))});
  return Object.fromEntries(Object.entries(v).map(([k,p])=>[k,tables(p)]));
 }
 // A table row or column list may itself share a previous value. Resolve
 // pointers before interpreting the table, rather than assuming literal rows.
 return tables(walk(encoded));
}
