test('every selected Qiongtong paragraph has a clause record, including prose without regex predicates',()=>{let entries=0,contexts=0,paragraphs=new Set();const H={子:'癸',丑:'己癸辛',寅:'甲丙戊',卯:'乙',辰:'戊乙癸',巳:'丙戊庚',午:'丁己',未:'己丁乙',申:'庚壬戊',酉:'辛',戌:'戊辛丁',亥:'壬甲'};for(const dm of '甲乙丙丁戊己庚辛壬癸')for(const month of '寅卯辰巳午未申酉戌亥子丑'){const z=structure('庚丙'+dm+'壬',month),f={dm,stems:Object.entries(z.pillars).map(([pillar,p])=>({pillar,stem:p.gan})),hidden:Object.entries(z.pillars).flatMap(([pillar,p])=>Array.from(H[p.zhi]).map(stem=>({pillar,branch:p.zhi,stem})))},r=c.JYBaziQiongtong.evaluate(f);assert.equal(r.clauseCoverage.paragraphs,r.clauseCoverage.representedParagraphs);assert.equal(r.clauseCoverage.totalClauses,r.checks.length);assert.equal(new Set(r.checks.map(p=>p.id)).size,r.checks.length);for(const p of r.checks.filter(p=>!p.machineTestable)){assert.equal(p.observablePremises,'no-literal-predicate');assert.notEqual(p.fullRuleStatus,'observable-premises-present');contexts++;}r.sourceParagraphs.forEach(p=>paragraphs.add(p.paragraph));entries++;}assert.equal(entries,120);assert(contexts>100);audits.push({method:'qiongtong-source-clause-coverage',entries,uniqueParagraphIds:paragraphs.size,contextOnlyOccurrences:contexts});});
